namespace cosmos {
StateBundle CSTStateEngine::update(double dt,const Simulation&sim){StateBundle out{};const auto&a=sim.sensors;const auto&p=sim.planet;const auto&pl=sim.player;const auto&w=sim.world;double freqMass=clamp(a.audioAvg*1.8),phase=std::atan2((a.mid-a.bass)+std::sin((sim.clock.simUnixMs*.001)*.11)*.05,(a.treble+.05))*1.2,flat=clamp(a.spectralFlatness),phaseVel=clamp(normAngle(phase-prevPhase_)/std::max(.001,dt)/8.0,-1.0,1.0);prevPhase_=phase;double visual=clamp(a.visionLuminance),ent=clamp(1-std::abs(freqMass-visual*.9)),valence=clamp(.5+(visual-.5)*.55+(w.biosphere-.4)*.28,-1.0,1.0),arousal=clamp(freqMass*.75+a.visionMotion*.55+w.storm*.25),dominance=clamp(.45+pl.speed*.025+p.gravityG*.08),psi=clamp(std::sqrt((a.bass*a.bass+a.mid*a.mid+a.treble*a.treble)/3.0)*1.8),phiH=clamp(1-std::abs(((a.dominantHz>1?a.dominantHz:220)/std::max(1.0,(a.spectralCentroid>1?a.spectralCentroid:440)))-1/PHI)),av=clamp(1-std::abs(arousal-a.visionMotion*.8-visual*.2)),qe=fract(std::sin(std::fmod(sim.clock.simUnixMs,100000.0)*.000071+double(p.seed%100000)*.00001+freqMass*5)*43758.5453);double b12[12]={freqMass,phase,flat,phaseVel,ent,valence,arousal,dominance,psi,phiH,av,qe};for(int i=0;i<12;i++)out.d12[i]=(float)b12[i];constexpr double sigma=10,rho=28,beta=8.0/3.0,scale=.035;double dx=sigma*(ly_-lx_),dy=lx_*(rho-lz_)-ly_,dz=lx_*ly_-beta*lz_;lx_+=dx*dt*scale;ly_+=dy*dt*scale;lz_+=dz*dt*scale;if(std::abs(lx_)>80||std::abs(ly_)>80||std::abs(lz_)>80){lx_=.1;ly_=.2;lz_=.3;}double chaos=clamp(std::hypot(lx_,ly_,lz_)/55.0),lat=a.locationOk?a.latitude/90:0,lon=a.locationOk?a.longitude/180:0,solar=std::sin(sim.clock.localDay*PI*2)*PI/2,slope=clamp(std::abs(fbm(p.seed,pl.x+2,pl.z)-fbm(p.seed,pl.x-2,pl.z))*2.3),civilization=clamp(w.outposts.size()*.06+w.biosphere*.16),resources=scanResource(sim),anomaly=clamp(w.anomalies*.08+w.storm*.15+chaos*.18),memC=clamp(1-std::abs(w.biosphere-memory_[0])),novelty=clamp(std::abs(qe-memory_[1])*.9+anomaly*.5),instability=clamp(chaos*.4+flat*.25+w.storm*.4),coherence=clamp(ent*.28+av*.26+memC*.2+(1-instability)*.26);double ext[30]={lx_/25,ly_/30,lz_/45,chaos,clamp(arousal*.7+w.storm*.4),clamp((freqMass+visual+w.biosphere)/3),clamp(a.spectralCentroid/12000),visual,a.visionMotion,a.visionEntropy,lat,lon,clamp(.5+solar/PI),clamp(p.gravityG/3),clamp(std::log10(p.atmosphereAtm+1)/3),clamp((p.temperatureC+220)/650),clamp(std::log10(p.pressurePa+1)/7),p.wind,slope,p.water,w.biosphere,civilization,p.radiation,clamp(p.magnetic/5),resources,anomaly,memC,novelty,instability,coherence};for(int i=0;i<12;i++)out.d42[i]=out.d12[i];for(int i=0;i<30;i++)out.d42[12+i]=(float)ext[i];double wavg=std::accumulate(weights_.begin(),weights_.end(),0.0)/12.0,hebb=clamp(wavg*coherence),plastic=clamp(.15+novelty*.65+(1-coherence)*.2),attention=clamp(arousal*.35+novelty*.4+coherence*.25),curiosity=clamp(novelty*.7+resources*.3),avoid=clamp(p.radiation*.35+w.storm*.35+instability*.3),flora=clamp(.7+w.biosphere*.3),bh=clamp(1-anomaly*.6),memDepth=clamp(w.cycles/120),predErr=clamp(std::abs(memory_[2]-coherence)),lr=clamp(.03+plastic*.17),resonance=clamp((phiH+ent+coherence+memC)/4),singularity=clamp(std::abs(phaseVel)*.25+instability*.35+(1-coherence)*.4);double adapt[12]={hebb,plastic,attention,curiosity,avoid,flora,bh,memDepth,predErr,lr,resonance,singularity};for(int i=0;i<42;i++)out.d54[i]=out.d42[i];for(int i=0;i<12;i++){out.d54[42+i]=(float)adapt[i];weights_[i]=(float)clamp(weights_[i]+lr*(adapt[i]*out.d12[i]-weights_[i])*.02);memory_[i]=(float)lerp(memory_[i],out.d12[i],clamp(dt*.15));}return out;}
}
